function newest(rows, keys) {
  return rows.slice().sort((a, b) => {
    const ta = Date.parse(a[keys[0]] || a[keys[1]] || 0) || 0;
    const tb = Date.parse(b[keys[0]] || b[keys[1]] || 0) || 0;
    return tb - ta;
  })[0];
}
function num(v) {
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  const n = Number(String(v ?? '').replace(/[^\d.]/g, ''));
  return Number.isFinite(n) ? n : 0;
}
function text(v) {
  return String(v ?? '').trim();
}

const hook = $('Webhook').first().json;
const body = hook.body && typeof hook.body === 'object' ? hook.body : hook;
const req = newest($('Get Buyer Requests').all().map((i) => i.json), ['Last Updated', 'Date Received']);
if (!req) throw new Error('No Buyer Requests row');

const requestId = text(body.requestId || req['Request ID']);
const selectedName = text(body.supplierName || req['Selected Supplier']);
const product = text(body.product || req['Product Name']);
const offers = $('Get Supplier Offers').all().map((i) => i.json);

const matched = offers.filter((o) => {
  const sameRequest = text(o['Linked Request ID']).toLowerCase() === requestId.toLowerCase();
  const sameSupplier = text(o['Supplier Name']) === selectedName;
  const sameProduct = text(o['Product Name']).toLowerCase() === product.toLowerCase();
  return sameRequest && sameSupplier && sameProduct;
});
const offer = newest(matched, ['Received At', 'Last Updated']);
if (!offer) throw new Error('No offer for ' + selectedName + ' / ' + product + ' on ' + requestId);

const unit = num(body.supplierUnitPrice || offer['Unit Price (per MT)']);
const indication = num(req['Target Price']);
if (unit <= 0) throw new Error('Supplier unit price missing');
if (indication > 0 && Math.abs(unit - indication) < 0.001) {
  throw new Error('Refusing supplier pack: price equals buyer indication ' + indication);
}

const email = text(offer['Supplier Email']);
if (!email.includes('@')) throw new Error(selectedName + ' has no Supplier Email');

const digits = requestId.replace(/\D/g, '');
const shared = {
  product,
  quantity_mt: num(req['Quantity (MT)']) || num(offer['Quantity Available (MT)']),
  supplierUnitPrice: unit,
  currency: text(offer.Currency) || 'USD',
  incoterm: text(offer.Incoterm) || text(req.Incoterm),
  load_port: text(offer['Load Port']),
  discharge_port: text(req['Destination Port']),
  packing: text(offer['Packing Type']),
  origin: text(offer.Origin),
  payment_terms: text(offer['Payment Terms']),
  shipping: text(req['Delivery/Shipment Window']),
  reference: requestId,
  supplier: { name: text(offer['Supplier Name']), email },
};

return [
  { json: { ...shared, document: 'purchase_order', order_ref: 'PO-' + digits.padStart(4, '0') } },
  { json: { ...shared, document: 'purchase_contract', order_ref: 'AQ-TE-' + digits.padStart(6, '0') } },
  { json: { ...shared, document: 'documentary_instructions', order_ref: 'AQ-TE-' + digits.padStart(6, '0') } },
];

const files = $('Convert to File').all();
const deal = $('Build supplier pack').first().json;

const pick = (part) => {
  const row = files.find((i) => String(i.binary?.data?.fileName || '').toLowerCase().includes(part));
  const file = row?.binary?.data;
  if (!file) throw new Error('Missing PDF binary for ' + part);
  return file;
};

if (Number(deal.supplierUnitPrice) === Number($('Get Buyer Requests').first().json['Target Price'])) {
  throw new Error('Will not email supplier at buyer indication price');
}

return [
  {
    json: {
      to: deal.supplier.email,
      name: deal.supplier.name,
      product: deal.product,
      qty: deal.quantity_mt,
      price: deal.supplierUnitPrice,
      reference: deal.reference,
    },
    binary: {
      po: pick('purchase_order'),
      contract: pick('purchase_contract'),
      instructions: pick('documentary'),
    },
  },
];
